L000536	\section{Design for Gaussian PMF}
L000537	
L000538	\par To realize a nearly factorable biphoton state, we design the crystal’s nonlinear
L000539	domain structure to generate a Gaussian-shaped phase-matching function (PMF).
L000540	We define the phase mismatch as
L000541	\begin{equation}
L000542	\Delta k = k_p - k_s - k_i - \frac{2\pi}{\Lambda},
L000543	\end{equation}
L000544	where $k_p$, $k_s$, and $k_i$ are the pump, signal, and idler wavevectors,
L000545	and $\Lambda$ is the quasi-phase-matching period.
L000546	The target PMF in the spatial-frequency domain is chosen as
L000547	\begin{equation}
L000548	\phi_{\mathrm{target}}(\Delta k)
L000549	= \exp\!\left(-\frac{\sigma^{2}}{2}\Delta k^{2}\right),
L000550	\end{equation}
L000551	where $\sigma$ controls the bandwidth of the target PMF.
L000552	
L000553	Performing an inverse Fourier transform yields the corresponding target nonlinear
L000554	profile in the spatial domain. For a crystal of finite length $L$, the Gaussian
L000555	profile is centered at $z=L/2$:
L000556	\begin{equation}
L000557	\Phi_{\mathrm{target}}(z)
L000558	= \frac{1}{\sqrt{2\pi}\sigma}
L000559	\exp\!\left[-\frac{(z - L/2)^{2}}{2\sigma^{2}}\right],
L000560	\end{equation}
L000561	where $z$ denotes the longitudinal position along the poled crystal.
L000562	
L000563	The cumulative nonlinear amplitude generated from the poling start position
L000564	$(z=0)$ to a position $z$ is obtained by integrating
L000565	$\Phi_{\mathrm{target}}(z)$:
L000566	\begin{align}
L000567	A_{\mathrm{target}}(z)
L000568	&= C\int_{0}^{z}
L000569	\frac{1}{\sqrt{2\pi}\sigma}
L000570	\exp\!\left[-\frac{(z' - L/2)^{2}}{2\sigma^{2}}\right]
L000571	dz' \notag \\
L000572	&= C\left[
L000573	\mathrm{erf}\!\left(\frac{L}{2\sqrt{2}\sigma}\right)
L000574	-
L000575	\mathrm{erf}\!\left(\frac{L - 2z}{2\sqrt{2}\sigma}\right)
L000576	\right],
L000577	\end{align}
L000578	where $C$ is a normalization constant.
L000579	
L000580	For a periodically poled structure with binary domain orientation
L000581	$g(z)=\pm1$, the PMF is given by
L000582	\begin{equation}
L000583	\phi(\Delta k)
L000584	= \int_{0}^{L} g(z)\, e^{i\Delta k z}\, dz .
L000585	\end{equation}
L000586	The contribution of the $j$th domain of length $L_c$ is
L000587	\begin{equation}
L000588	\int_{(j-1)L_c}^{jL_c} g[j]\, e^{i\Delta k z'}\, dz'
L000589	= g[j]\,
L000590	\frac{e^{i\Delta k j L_c}-e^{i\Delta k (j-1)L_c}}{i\Delta k}.
L000591	\end{equation}
L000592	Summing over all domains yields the discrete PMF
L000593	\begin{equation}
L000594	\phi(\Delta k)
L000595	= \sum_{j=1}^{N}
L000596	g[j]\,
L000597	\frac{e^{i\Delta k j L_c}-e^{i\Delta k (j-1)L_c}}{i\Delta k},
L000598	\qquad
L000599	N = \frac{L}{L_c}.
L000600	\end{equation}
L000601	Equivalently,
L000602	\begin{equation}
L000603	\phi(\Delta k)
L000604	= \frac{e^{i\Delta k L_c}-1}{i\Delta k}
L000605	\sum_{j=1}^{N} g[j]\, e^{i\Delta k (j-1)L_c},
L000606	\end{equation}
L000607	where $(e^{i\Delta k L_c}-1)/(i\Delta k)$ represents the contribution of a
L000608	single domain, and the summation describes the coherent accumulation of all
L000609	domains.
L000610	
L000611	To determine the binary domain sequence $g[j]=\pm1$, we employ a
L000612	cumulative-error minimization algorithm. Each domain orientation is chosen
L000613	such that the discrete cumulative nonlinear amplitude
L000614	\begin{equation}
L000615	A[j] = \sum_{m=1}^{j} g[m]\,L_c
L000616	\end{equation}
L000617	best approximates the target function
L000618	$A_{\mathrm{target}}(jL_c)$.
L000619	This procedure produces a domain sequence whose resulting PMF closely
L000620	approximates the desired Gaussian profile.
L000621	The biphoton joint spectral amplitude (JSA) can be expressed via Schmidt
L000622	decomposition as
L000623	\begin{equation}
L000624	f(\omega_s,\omega_i)
L000625	= \sum_{n} c_n\,
L000626	\chi_n(\omega_s)\,
L000627	\varphi_n(\omega_i),
L000628	\end{equation}
L000629	where $\chi_n$ and $\varphi_n$ are orthonormal mode functions and
L000630	$\sum_n |c_n|^2 = 1$.
L000631	The spectral purity is given by
L000632	\begin{equation}
L000633	P = \sum_n |c_n|^4,
L000634	\end{equation}
L000635	with $P=1$ corresponding to a fully factorable biphoton state.
